def transform(grid):
    if not grid or not grid[0]:
        return []

    W = len(grid[0])
    center = grid[0].index(2)
    H = 2 * (center + 1)

    output = [[0] * W for _ in range(H)]

    for r in range(H):
        c_diff = r - (1 if 4 <= r < 6 else 0)
        c1, c2 = center - c_diff, center + c_diff

        if c_diff == 0:
            output[r][center] = 2
        elif 0 <= c1 < W:
            output[r][c1] = 2
        if 0 <= c2 < W:
            output[r][c2] = 2

        if 0 <= c1 < W and 0 <= c2 < W:
            if c_diff == 3:
                output[r][center - 1] = 1
            elif c_diff == 4:
                output[r][center] = 1
            elif c_diff == 6:
                output[r][center - 2] = 1
                output[r][center + 2] = 1
        elif not (0 <= c1 < W) and not (0 <= c2 < W):
            if c_diff >= 10:
                mod = 0
            else:
                mod = (r - 2) % 4
            for c in range(W):
                if output[r][c] == 0 and c % 4 == mod:
                    output[r][c] = 1

    return output

